    const sz = (s) => { s.setAttribute('style', 'width:26px;height:26px;fill:none;stroke:#2a6fc9;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;flex:none'); return s; };   // outside #tc: the icon's size is set here
    const top = chromeIOS(), step = (n, i, s) => el('div', { style: 'display:flex;align-items:center;gap:10px;margin:8px 0' }, el('span', { style: 'width:26px;height:26px;border-radius:50%;background:#2a6fc9;color:#fff;display:grid;place-items:center;font-weight:600;flex:none', text: String(n) }), i, el('span', { text: s }));
    const arrow = el('div', { id: 'tc-ios-arrow', 'data-pos': top ? 'top' : 'bottom', style: 'display:flex;justify-content:' + (top ? 'flex-end' : 'center') + ';color:#2a6fc9;' + (top ? 'transform:rotate(180deg)' : '') }, sz(ic('down')));
    const card = el('div', { style: 'background:#fff;color:#2e3436;border-radius:18px;padding:16px 16px 12px;box-shadow:0 10px 36px rgba(0,0,0,.3);max-width:min(92vw,380px);margin:0 auto;font:15px/1.4 -apple-system,"Apple SD Gothic Neo",system-ui,sans-serif' },
      el('b', { style: 'display:block;font-size:17px;margin-bottom:4px', text: T('Add to Home Screen to get notifications', '알림을 받으려면 홈 화면에 추가하세요') }),
      step(1, sz(ic('share')), top ? T('Tap the Share button at the top right.', '오른쪽 위의 공유 단추를 누르세요.') : T('Tap the Share button at the bottom.', '아래쪽의 공유 단추를 누르세요.')),
      step(2, sz(ic('plus')), T('Choose "Add to Home Screen", then open NanumOS from the new icon.', '「홈 화면에 추가」를 고른 뒤, 새 아이콘으로 나눔OS를 여세요.')),
      el('p', { style: 'font-size:12.5px;color:#68676e;margin:6px 0', text: T('The Home Screen app keeps its own data: back up in Safari first, then restore in the Home Screen app.', '홈 화면 앱은 사파리와 저장소가 따로예요 — 사파리에서 백업 → 홈 화면 앱에서 되살리기.') }),
      el('button', { id: 'tc-ios-guide-close', style: 'display:block;margin:4px 0 0 auto;padding:8px 14px;color:#2a6fc9;font:inherit;font-weight:600;border:0;background:none', on: { click: closeIosGuide } }, T('Close', '닫기')));
    const d = el('div', { id: 'tc-ios-guide', role: 'dialog', 'data-pos': top ? 'top' : 'bottom', style: 'position:fixed;left:0;right:0;z-index:99999;padding:0 10px;' + (top ? 'top:max(8px,env(safe-area-inset-top))' : 'bottom:max(8px,env(safe-area-inset-bottom))') }, ...(top ? [arrow, card] : [card, arrow]));
