    if (m.kind === 'text') it.x = m.text || ''; else if (m.kind === 'emo') it.c = m.code;
    if (m.re && typeof m.re.id === 'string') it.re = c.side === 'g' ? { id: m.re.id.slice(c.room.length + 1), from: m.re.mine ? c.slot : m.re.from, text: m.re.text || '' } : { id: m.re.id.slice(c.room.length + 1), me: !!m.re.mine, text: m.re.text || '' };
    if ((m.kind === 'photo' || m.kind === 'voice') && m.blob) { it.mime = m.mime || m.blob.type; it.size = m.blob.size; it.secs = m.secs || 0; if (m.x) it.xx = m.x; }
