      if (!m || !SYK.has(m.kind) || (m.exp && m.exp <= now)) continue;   // a disappearing message whose time is up is never handed over
      const it = syOut(c, m);
      if (it.size && (s.syBytes || 0) + it.size > SY_MAXBYTES) break;
      const j = JSON.stringify(it).length + (it.x ? it.x.length * 2 : 0); if (blen + j > 40000) await flush(); batch.push(it); blen += j; n++;
