    if (it.k === 'photo' || it.k === 'voice') { const size = +it.size; if (!(size > 0 && size <= 8 * 1048576)) return null; m.mime = mimeOK(it.mime); m.size = size; m.secs = Math.max(0, Math.min(3600, +it.secs || 0)); if (it.xx) m.x = xOf(it.xx); }
