      for (const e of y.list) { const w = e.split('.')[0], m = all.get(c.room + ':' + w); if (y.want.has(w) || (m && (m.del || here.get(w) === e || (m.mine && m.status === 'wait'))) || (!m && (c.swept || []).includes(w))) continue; y.want.add(w); y.todo.push(w); }
