    root.__place = place; place(); window.addEventListener('resize', place);
    const fit = () => { const vv = window.visualViewport; if (!vv) return; root.style.setProperty('--vvh', vv.height + 'px'); root.__place(); };
    if (window.visualViewport) { visualViewport.addEventListener('resize', fit); visualViewport.addEventListener('scroll', fit); }
    return root;
