  const domOf = (addr) => (addr.split('@')[1] || '').trim().toLowerCase(), alias = { 'googlemail.com': 'gmail.com', 'hanmail.net': 'daum.net', 'me.com': 'icloud.com', 'mac.com': 'icloud.com', 'hotmail.com': 'outlook.com', 'live.com': 'outlook.com' };
