    const cur = edit ? dec.decode(readMain('/home/zeus/.mail/account') || new Uint8Array()) : '', val = (k) => ((cur.match(new RegExp('^' + k + ' (.*)$', 'm')) || [])[1] || '');
    $('title').textContent = edit ? '메일 계정' : '메일 계정 추가'; $('remove').hidden = !edit; err.textContent = ''; pw.value = '';
