    for (const b of f.querySelectorAll('.prov button')) b.onclick = () => { const name = addr.value.split('@')[0]; addr.value = b.dataset.d ? name + '@' + b.dataset.d : name + '@'; show(); addr.focus(); };
    addr.oninput = show; show();
